    always_ff @(posedge clk or negedge rst_n) begin
        if (!rst_n) v_r <= '0;
        else        v_r <= {v_r[8:0], in_valid};
    end

    // ---- after the last register: aligned syndrome and codeword -> corrector ----
    logic  [6:0] syn;
    logic [38:0] cw_q;
    assign syn[0] = s0_r10;
    assign syn[1] = s1_r10;
    assign syn[2] = s2_r10;
    assign syn[3] = s3_r10;
    assign syn[4] = s4_r10;
