    ecc_corr_cmp u_corr (.syn(syn), .flip(flip), .ce(hit));
    always_comb begin
        err_pos = 6'd0;
        for (int j = 0; j < 39; j++)
            if (flip[j]) err_pos = err_pos | 6'(j);
    end
    assign ce        = hit;
    assign ue        = (syn != 7'd0) && !hit;
    assign cw_out    = cw_q ^ flip;
    assign data_out  = cw_out[31:0];
    assign syndrome  = syn;
    assign out_valid = v_r[9];
