// Wrapper: choose the configuration with CFG (same ports as ecc_dec; latency = ecc_xl_pkg::xl_lat(CFG))
module ecc_dec_xl #(
    parameter int CFG = 0
)(
    input  logic        clk,
    input  logic        rst_n,
    input  logic        in_valid,
    input  logic [38:0] cw_in,
    output logic        out_valid,
    output logic [31:0] data_out,
    output logic [38:0] cw_out,
    output logic  [6:0] syndrome,
    output logic        ce,
    output logic        ue,
    output logic  [5:0] err_pos
);
    generate
        if (CFG == 0) begin : g_cfg0
            ecc_dec_xl_cfg0 u (.*);
        end else if (CFG == 1) begin : g_cfg1
            ecc_dec_xl_cfg1 u (.*);
        end else if (CFG == 2) begin : g_cfg2
            ecc_dec_xl_cfg2 u (.*);
        end else if (CFG == 3) begin : g_cfg3
            ecc_dec_xl_cfg3 u (.*);
        end else if (CFG == 4) begin : g_cfg4
            ecc_dec_xl_cfg4 u (.*);
        end else if (CFG == 5) begin : g_cfg5
            ecc_dec_xl_cfg5 u (.*);
        end else if (CFG == 6) begin : g_cfg6
            ecc_dec_xl_cfg6 u (.*);
        end
    endgenerate
endmodule
